import org.junit.jupiter.api.*; import org.openqa.selenium.*; import org.openqa.selenium.chrome.ChromeDriver; import org.openqa.selenium.chrome.ChromeOptions; import static org.junit.jupiter.api.Assertions.*;
public class EventFlowAuthorizationTest { static WebDriver driver; @BeforeAll static void setup(){ChromeOptions o=new ChromeOptions();o.addArguments("--headless=new","--no-sandbox","--disable-dev-shm-usage");driver=new ChromeDriver(o);} @AfterAll static void close(){if(driver!=null)driver.quit();} @Test void unauthenticatedAdminDevopsIsProtected(){driver.get(System.getProperty("baseUrl","http://localhost:3000")+"/admin/devops");assertTrue(driver.getCurrentUrl().contains("login")||driver.getPageSource().contains("Access Denied"));}}
